import{_ as a,o as r,c as e,ag as d}from"./chunks/framework.C5oN-8Wt.js";const n="/cns_master_docs/teaching-v0.3.0-alpha/06-filter.svg",g=JSON.parse('{"title":"06 保留需要的变化：低通滤波能做什么？","description":"","frontmatter":{},"headers":[],"relativePath":"v0.3.0-alpha/learn/06-filter/index.md","filePath":"v0.3.0-alpha/learn/06-filter/index.md"}'),s={name:"v0.3.0-alpha/learn/06-filter/index.md"};function l(i,t,o,h,p,c){return r(),e("div",null,[...t[0]||(t[0]=[d(`<h1 id="_06-保留需要的变化-低通滤波能做什么" tabindex="-1">06 保留需要的变化：低通滤波能做什么？ <a class="header-anchor" href="#_06-保留需要的变化-低通滤波能做什么" aria-label="Permalink to &quot;06 保留需要的变化：低通滤波能做什么？&quot;">​</a></h1><p>假设机地通信的某个处理环节需要保留缓慢变化的信号，却混入了较快的周期干扰和随机噪声。能否按“变化快慢”筛选？本课先规定 <strong>64 Hz 是要保留的成分，768 Hz 是要衰减的成分</strong>，再观察低通滤波器的作用。</p><p>适用 CNS Master <strong>v0.3.0-alpha</strong>。先完成<a href="./../05-noise/">05 信号与噪声</a>。本例是选频原理仿真，64 Hz 不代表无人机的位置更新率，也不代表无线电载频。</p><p><a href="../../../downloads/teaching-v0.3.0-alpha/06-filter.cnsproj" download>下载本课工程：06-filter.cnsproj</a></p><h2 id="学习目标与必要知识" tabindex="-1">学习目标与必要知识 <a class="header-anchor" href="#学习目标与必要知识" aria-label="Permalink to &quot;学习目标与必要知识&quot;">​</a></h2><p>完成后应能在频谱上指出被保留、被衰减的成分，并说明“看起来更平滑”为什么还不够。</p><p><strong>低通</strong>表示较低频率较容易通过、较高频率受到衰减。<strong>截止频率</strong>标示选频边界附近的位置；真实有限长度滤波器有一段<strong>过渡带</strong>，通过与阻挡不会在一条竖线上瞬间切换。衰减表示幅度减小，不保证变为严格的零。</p><h2 id="接线与参数理由" tabindex="-1">接线与参数理由 <a class="header-anchor" href="#接线与参数理由" aria-label="Permalink to &quot;接线与参数理由&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>信号源 1：64 Hz  ──→ 加法器 1.in1</span></span>
<span class="line"><span>信号源 2：768 Hz ──→ 加法器 1.in2</span></span>
<span class="line"><span>噪声源 1        ──→ 加法器 1.in3</span></span>
<span class="line"><span>                         out ──→ 低通滤波器 1.in</span></span></code></pre></div><p>混合输出和滤波输出都保留观察支路。<strong>观察支路只取数，不改变主链计算。</strong></p><table tabindex="0"><thead><tr><th>位置</th><th>本课值</th><th>为什么选它</th></tr></thead><tbody><tr><td>信号源 1</td><td>正弦 64 Hz，幅度 1，初相 0，偏置 0</td><td>需要保留的低频参照</td></tr><tr><td>信号源 2</td><td>正弦 768 Hz，幅度 0.5，初相 0，偏置 0</td><td>与低频相隔较远，便于看清选频效果</td></tr><tr><td>噪声源 1</td><td>高斯，幅度 0.1，固定种子 7</td><td>加入较小的随机扰动</td></tr><tr><td>三个源及低通输入采样率</td><td>4096 Hz</td><td>保持同速；最高的 768 Hz 低于 2048 Hz 奈奎斯特频率</td></tr><tr><td>加法器 1</td><td>输入路数 3</td><td>将三路相加</td></tr><tr><td>低通滤波器 1</td><td>截止 256 Hz，过渡带宽 128 Hz，通带增益 1，Hamming 设计窗</td><td>64 Hz 远低于边界，768 Hz 远高于边界，避免一开始就在过渡带争论“通过多少”</td></tr><tr><td>抽取、插值</td><td>均为 1</td><td>本课不改变采样率，只研究选频</td></tr></tbody></table><p>Hamming 是设计滤波系数的一种窗，本课保持工程内设置。它与观察器计算频谱时使用的窗是两个用途不同的设置，不必把两者改成同一个名字。</p><h2 id="逐步操作" tabindex="-1">逐步操作 <a class="header-anchor" href="#逐步操作" aria-label="Permalink to &quot;逐步操作&quot;">​</a></h2><ol><li>下载工程，先按 Shift+F5 停止已有本地任务，再用 Ctrl+O 打开文件。核对连线以及两个信号源的编号和频率。</li><li>在运行前写下预测：混合输出应该有哪两个主要谱峰？经过低通后，哪一个应明显减小？</li><li>按 F5。工程中的观察器已绑定滤波前后输出。在“参数”页确认时域捕获为“加法器 1 → 输出”和“低通滤波器 1 → 输出”；另有两个独立频谱窗口，分别捕获这两个节点的“频谱”。</li><li>若自行绑定，从“编辑 → 插入 → 观察器”打开工具，在参数页逐项点选候选。两路时域可放在同一个观察器。两个频谱也支持同窗叠加，或像下载工程一样各开一窗；不将时域与频谱混在同一图。瀑布模式需要恰好一路频谱。</li><li>先看频谱，横轴显示 <strong>0—2048 Hz</strong>，两路采用相同幅度刻度。找到 64 Hz、768 Hz，比较同一频率处滤波前后的高度，不只比较各自最高的峰。</li><li>再看时域“曲线叠加”。把全宽缩到约 <strong>0.0625 s</strong>，观察较慢的周期骨架及其上的快速起伏。滤波后可能有时间滞后，启动初段也有过渡；不要拖动一条曲线把它强行对齐。</li><li>等待稳定数据后按 Shift+F5。需要细看时可拖动图像回看；“自动刻度”恢复最新数据。将工程另存为自己的练习文件，记录保留、衰减的频率及坐标单位。</li></ol><h2 id="预期图像与解释" tabindex="-1">预期图像与解释 <a class="header-anchor" href="#预期图像与解释" aria-label="Permalink to &quot;预期图像与解释&quot;">​</a></h2><p><a href="/cns_master_docs/teaching-v0.3.0-alpha/06-filter.svg"><img src="`+n+'" alt="实际 GNU 输出：滤波前后，以及截止频率由 256 放宽到 1024 Hz 的单参对照"></a></p><p>参考图连接实际采样值，包含启动段；右边比较两个截止频率的低通输出。它不是 Master 截图，稳定后的频谱仍应在自己的观察器中按以下步骤核对。</p><p>混合频谱应能辨认 64 Hz 与 768 Hz 两个主要成分，噪声还会形成起伏的背景。低通输出在 64 Hz 附近仍有明显谱峰，768 Hz 附近则明显减小；不要要求峰高恰好等于输入参数，也不要把有限数值误差当作异常。</p><p>时域中，滤波输出更接近缓慢变化的正弦，但这只是与本课目标一致的外观。判断依据是：<strong>64 Hz 成分保留、768 Hz 成分受到衰减</strong>。低通也会放过一部分低频噪声，无法把所有噪声都删除。若需要的信息本来就在高频，盲目低通也会把有用成分一起损伤。</p><p>滤波器需要利用相邻样本，会带来延迟和启动过程。两路同一横坐标不保证代表已经补偿过延迟的同一波峰；本课不据两条曲线的逐点相减计算误差。</p><h2 id="单参数对照-把截止频率放宽到-1024-hz" tabindex="-1">单参数对照：把截止频率放宽到 1024 Hz <a class="header-anchor" href="#单参数对照-把截止频率放宽到-1024-hz" aria-label="Permalink to &quot;单参数对照：把截止频率放宽到 1024 Hz&quot;">​</a></h2><ol><li>停止运行，只把低通滤波器的“截止频率”由 <strong>256 改为 1024 Hz</strong>。过渡带宽仍为 128 Hz，其他参数和连线保持不变。</li><li>按 F5 重新运行，使用同样的频谱范围和纵轴刻度。</li><li>查看 768 Hz 附近是否重新出现明显谱峰。解释：这一成分没有改变，是滤波器允许通过的范围变宽了。</li><li>恢复截止 256 Hz，再重新运行核对。</li></ol><p>请完成一句话：“截止频率越高，_______，所以不一定滤得越干净。”可填“允许通过的高频范围越宽”，再联系你看到的 768 Hz 成分解释。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>现象</th><th>检查方法</th></tr></thead><tbody><tr><td>滤波前后完全相同</td><td>检查是否绑定到同一个输出，以及运行快照中的截止频率是否为本轮值</td></tr><tr><td>准备提示速率不一致</td><td>三个源和滤波器输入采样率均应为 4096；不要通过只改滤波器 Fs 来移动边界</td></tr><tr><td>768 Hz 仍有很小的值</td><td>有限 FIR、噪声和有限长度频谱不会保证严格零；比较同刻度下的衰减程度</td></tr><tr><td>滤波输出波峰位置较晚</td><td>先考虑滤波延迟与启动过渡，不把它直接称为网络延迟或丢包</td></tr><tr><td>只看见一个周期，无法读数</td><td>放大横轴范围查看几个周期；缩放显示不会改变实际计算参数</td></tr></tbody></table><p>到这里，你已经用“时间上怎样变”和“包含哪些频率”两种方式解释同一数据。下一课用<a href="./../07-iq/">两个坐标理解 I/Q</a>，为相位与数字星座建立直觉。</p><p>模块参考：<a href="./../../modules/low_pass/">低通滤波器</a> · <a href="./../../modules/add/">加法器</a> · <a href="./../">返回学习路径</a></p>',27)])])}const z=a(s,[["render",l]]);export{g as __pageData,z as default};
